@media (max-width:1366px) and (min-height:769px){#bobbyProgramsSection{padding:65px 40px;}#bobbyProgramsMainTitle{font-size:46px;}#bobbyProgramsSubtitle{font-size:16px;max-width:420px;}.bobbyProgramBlock{min-height:480px;}#bobbyProgramText1,#bobbyProgramText2,#bobbyProgramLabel1,#bobbyProgramLabel2{font-size:27px;}#bobbyProgramDesc1,#bobbyProgramDesc2{font-size:14px;margin-bottom:28px;}}
