@media (max-width:768px){#bobbyProgramsSection{padding:50px 20px;min-height:auto;}#bobbyProgramsHeader{margin-bottom:40px;gap:20px;}#bobbyProgramsMainTitle{font-size:32px;}#bobbyProgramsSubtitle{font-size:14px;}#bobbyProgramsContainer{flex-direction:column;gap:20px;}.bobbyProgramBlock{width:100%;min-height:400px;}#bobbyProgramImage1,#bobbyProgramImage2{min-height:400px;}#bobbyProgramOverlay1,#bobbyProgramOverlay2{padding:40px 25px;}#bobbyProgramText1,#bobbyProgramText2,#bobbyProgramLabel1,#bobbyProgramLabel2{font-size:24px;}#bobbyProgramDesc1,#bobbyProgramDesc2{font-size:13px;margin-bottom:25px;max-width:100%;}#bobbyProgramBtn1,#bobbyProgramBtn2{font-size:13px;padding:10px 24px;bottom:60px;left:25px;}#bobbyProgramBadge1,#bobbyProgramBadge2{bottom:40px;right:25px;padding:10px 16px;}#bobbyProgramBadgeBottom1,#bobbyProgramBadgeBottom2{font-size:14px;}}
