@media (max-width:480px){#bobbyProgramsSection{padding:35px 15px;}#bobbyProgramsHeader{margin-bottom:30px;gap:15px;}#bobbyProgramsMainTitle{font-size:24px;}#bobbyProgramsSubtitle{font-size:12px;}#bobbyProgramsContainer{gap:15px;min-height:auto;}.bobbyProgramBlock{width:100%;min-height:320px;}#bobbyProgramImage1,#bobbyProgramImage2{min-height:320px;}#bobbyProgramOverlay1,#bobbyProgramOverlay2{padding:30px 18px;}#bobbyProgramText1,#bobbyProgramText2,#bobbyProgramLabel1,#bobbyProgramLabel2{font-size:18px;}#bobbyProgramDesc1,#bobbyProgramDesc2{font-size:11px;margin-bottom:20px;}#bobbyProgramBtn1,#bobbyProgramBtn2{font-size:11px;padding:8px 16px;bottom:50px;left:18px;}#bobbyProgramBadge1,#bobbyProgramBadge2{bottom:30px;right:18px;padding:8px 12px;}#bobbyProgramBadgeTop1,#bobbyProgramBadgeTop2{font-size:8px;}#bobbyProgramBadgeBottom1,#bobbyProgramBadgeBottom2{font-size:11px;}}
@media (max-width:360px){#bobbyProgramsSection{padding:30px 12px;}#bobbyProgramsHeader{margin-bottom:25px;gap:12px;}#bobbyProgramsMainTitle{font-size:20px;}#bobbyProgramsSubtitle{font-size:11px;}#bobbyProgramsContainer{gap:12px;}.bobbyProgramBlock{min-height:280px;}#bobbyProgramImage1,#bobbyProgramImage2{min-height:280px;}#bobbyProgramOverlay1,#bobbyProgramOverlay2{padding:25px 15px;}#bobbyProgramText1,#bobbyProgramText2,#bobbyProgramLabel1,#bobbyProgramLabel2{font-size:16px;}#bobbyProgramDesc1,#bobbyProgramDesc2{font-size:10px;margin-bottom:18px;}#bobbyProgramBtn1,#bobbyProgramBtn2{font-size:10px;padding:6px 12px;bottom:45px;left:15px;}#bobbyProgramBadge1,#bobbyProgramBadge2{bottom:25px;right:15px;padding:6px 10px;}#bobbyProgramBadgeTop1,#bobbyProgramBadgeTop2{font-size:7px;}#bobbyProgramBadgeBottom1,#bobbyProgramBadgeBottom2{font-size:10px;}}
